import re
def apply(script, message):
    insert = 'a = 2\n'
    m = re.search(r"'([^']+)'", message)
    if m:
        bad_name = m.group(1)
        for col_name, placeholder in {}.items():
            insert = insert.replace(placeholder, "'" + bad_name + "'")
    if insert not in script:
        script += insert
    return script
